import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { InventoryError } from "../src/inventory.ts";

// ── Helpers ──────────────────────────────────────────────────────────

const mkProduct = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

// ── Cart line management ─────────────────────────────────────────────

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(mkProduct("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("throws on non-positive quantity", () => {
    expect(() => cart.add(mkProduct("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 1000), -1)).toThrow(RangeError);
  });

  it("throws on non-integer quantity", () => {
    expect(() => cart.add(mkProduct("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("throws on negative unitPriceCents", () => {
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a known product and returns true", () => {
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing an unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    cart.add(mkProduct("a", 1000), 3);
    cart.updateQuantity("a", 7);
    expect(cart.itemCount).toBe(7);
  });

  it("updateQuantity with 0 removes the line", () => {
    cart.add(mkProduct("a", 1000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("x", 5)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity throws for negative quantity", () => {
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("b", 2000), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(mkProduct("a", 1000), 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // original cart unaffected
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

// ── Cart totals (pricing pipeline) ───────────────────────────────────

describe("Cart — totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents × quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("b", 500), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500); // 2000 + 1500
  });

  it("empty cart produces all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount from injected policy", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(200);
    expect(totals.subtotalCents).toBe(1000);
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps discount to [0, subtotal]", () => {
    // discount exceeds subtotal
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(5000),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(mkProduct("a", 1000), 1);
    const totals = cart.totals();
    // tax should be computed on discounted subtotal = 1000 - 200 = 800
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(totals.taxCents).toBe(80);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("computes shipping on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(mkProduct("a", 1000), 1);
    const totals = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800, // discounted subtotal
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(mkProduct("a", 1000), 1);
    const totals = cart.totals();
    // discounted = 1000 - 100 = 900
    // total = 900 + 72 + 500 = 1472
    expect(totals.totalCents).toBe(1472);
  });

  it("uses default seams (no discount, no tax, free shipping) when unconfigured", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("defaults region to US", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

// ── Cart.checkout() ──────────────────────────────────────────────────

describe("Cart — checkout()", () => {
  it("returns totals and lines for a basic checkout", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("checks inventory and passes when available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );

    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );

    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({ region: "FR" });
    cart.add(mkProduct("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    // 20% of 1000 = 200
    expect(result.totals.taxCents).toBe(200);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
  });

  it("combines priceFetcher + discount + asyncTaxProvider + shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy,
      shippingCalculator,
      region: "US",
    });
    cart.add(mkProduct("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });
    // subtotal = 2000, discount clamped = 100, discounted = 1900
    // tax = floor(1900 * 0.1) = 190
    // shipping = 500
    // total = 1900 + 190 + 500 = 2590
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(190);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2590);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("checks inventory for multiple products; first denial wins", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({
          available: false,
          reason: "b is out of stock",
        }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).productId).toBe("b");
    }
  });

  it("works with no collaborators", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 4);
    const result = await cart.checkout({});
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.totalCents).toBe(2000);
  });

  it("passes availableQuantity=undefined when not provided in denial", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 3);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.available).toBeUndefined();
    }
  });
});
"}

