toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const mkLine = (
  id: string,
  weightGrams: number,
  qty: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 100, weightGrams },
  quantity: qty,
});

const mkLineNoWeight = (id: string, qty: number): CartLine => ({
  product: { id, name: id, unitPriceCents: 100 },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([mkLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flat cents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flat cents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 100.5)).toThrow(RangeError);
    });

    it("accepts zero flat cents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([mkLine("a", 200, 1)], 2000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([mkLine("a", 200, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([mkLine("a", 200, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([mkLine("a", 200, 1)], 4999)).toBe(599);
    });

    it("returns flat fee when no freeOverCents set regardless of subtotal", () => {
      const calc = new FlatShippingCalculator(599);
      expect(
        calc.computeShippingCents([mkLine("a", 200, 1)], 999_999),
      ).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      expect(
        calc.computeShippingCents([mkLineNoWeight("a", 3)], 5000),
      ).toBe(0);
    });

    it("selects first bracket (sorted) for weight within range", () => {
      // 200g × 1 = 200g → ≤ 500 bracket → 300
      expect(calc.computeShippingCents([mkLine("a", 200, 1)], 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // 500g exactly → ≤ 500 bracket → 300
      expect(calc.computeShippingCents([mkLine("a", 500, 1)], 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → > 500, ≤ 1000 bracket → 500
      expect(calc.computeShippingCents([mkLine("a", 501, 1)], 5000)).toBe(500);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g → ≤ 2000 bracket → 800
      expect(calc.computeShippingCents([mkLine("a", 2000, 1)], 5000)).toBe(800);
    });

    it("uses overflowCostCents when weight exceeds all brackets", () => {
      // 2001g → overflow → 1200
      expect(calc.computeShippingCents([mkLine("a", 2001, 1)], 5000)).toBe(
        1200,
      );
    });

    it("defaults overflow to heaviest bracket cost when not specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      // 1500g → overflow → last bracket cost = 500
      expect(
        noOverflow.computeShippingCents([mkLine("a", 1500, 1)], 5000),
      ).toBe(500);
    });

    it("handles multiple items summing weight", () => {
      // 400g × 2 = 800g → ≤ 1000 bracket → 500
      expect(calc.computeShippingCents([mkLine("a", 400, 2)], 5000)).toBe(500);
    });
  });
});

